// Unpack items array and prepare clean OpenAI Vision payload in memory
const items = $json.items || [];
return items
  .filter(item => item && item.imageUrl && item.imageUrl.startsWith('http'))
  .map(item => {
    const rawSnippet = item.rawText || item.title || '';
    const aiPayload = {
      model: 'gpt-4o-mini',
      messages: [
        {
          role: 'system',
          content: 'You are an expert automotive digital merchandising analyst. Extract vehicle lease, finance, or purchase specials from the promotional flyer image.\n\nReturn ONLY a valid JSON object matching this schema without markdown code blocks:\n{\n  "is_special": true,\n  "year": 2026,\n  "make": "Ford",\n  "model": "Explorer",\n  "trim": "XLT",\n  "special_type": "lease",\n  "monthly_payment": 389,\n  "term_months": 36,\n  "down_payment": 2999,\n  "apr": null,\n  "msrp": 42500,\n  "offer_details": null,\n  "title": "2026 Ford Explorer XLT Lease Special",\n  "disclaimer": "Full legal disclaimer...",\n  "expiration_date": "2026-10-31"\n}\n\nSTRICT QUALIFICATION & DISCARD RULES:\n1. is_special: A flyer is a valid special ONLY if it contains actionable numeric offer terms: such as a monthly payment ($/mo), APR rate (%), bonus cash/rebate/discount amount ($), lease/finance term (number of months), or down payment ($).\n2. If the flyer is general branding, an event announcement (e.g. "Sales Event"), dealership award/review, lifetime warranty/service pitch, or contains NO numbers/financial offer terms (no monthly payment, no APR %, no cash/discount amount, no term, no down payment), you MUST set "is_special": false, and set all numeric fields (monthly_payment, term_months, down_payment, apr, msrp) to null.\n3. special_type must be: "lease", "finance", "cash", or "service".\n4. All numerical fields must be clean numbers without "$", "%", or commas.\n5. If a field is not stated in the image, set it to null.\n6. expiration_date must be in YYYY-MM-DD format if visible, else null.'
        },
        {
          role: 'user',
          content: [
            {
              type: 'text',
              text: `Extract all special offer details for this flyer. Existing raw snippet: ${rawSnippet}`
            },
            {
              type: 'image_url',
              image_url: {
                url: item.imageUrl
              }
            }
          ]
        }
      ],
      response_format: { type: 'json_object' },
      max_tokens: 800,
      temperature: 0.1
    };

    return {
      json: {
        ...item,
        aiPayload
      }
    };
  });

// Clean and format AI responses for all incoming items
const allAiItems = $input.all();
const originalItems = $('Split Items for Processing').all();

return allAiItems.map((aiItem, index) => {
  const originalItem = originalItems[index]?.json || {};
  const aiResponse = aiItem.json?.choices?.[0]?.message?.content || '{}';
  let parsed = {};
  try {
    parsed = JSON.parse(aiResponse);
  } catch (e) {
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { parsed = JSON.parse(jsonMatch[0]); } catch {}
    }
  }

  const hasNumericTerms = (
    (parsed.monthly_payment != null && Number(parsed.monthly_payment) > 0) ||
    (parsed.apr != null && Number(parsed.apr) >= 0) ||
    (parsed.down_payment != null && Number(parsed.down_payment) >= 0) ||
    (parsed.term_months != null && Number(parsed.term_months) > 0) ||
    (parsed.msrp != null && Number(parsed.msrp) > 0) ||
    (parsed.offer_details && String(parsed.offer_details).trim().length > 0)
  );

  const isSpecial = parsed.is_special !== false && hasNumericTerms;

  return {
    json: {
      staging_id: originalItem.id,
      image_hash: originalItem.imageHash || null,
      auto_approve: isSpecial,
      status: isSpecial ? 'approved' : 'discarded',
      discard: !isSpecial,
      discard_reason: !isSpecial ? 'No actionable financial special terms (empty card avoided)' : null,
      raw_text: originalItem.rawText || '',
      extracted_data: {
        is_special: isSpecial,
        year: parsed.year || new Date().getFullYear(),
        make: parsed.make || 'Unknown',
        model: parsed.model || 'Special Offer',
        trim: parsed.trim || null,
        special_type: parsed.special_type || 'lease',
        monthly_payment: parsed.monthly_payment != null ? Number(parsed.monthly_payment) : null,
        term_months: parsed.term_months != null ? Number(parsed.term_months) : null,
        down_payment: parsed.down_payment != null ? Number(parsed.down_payment) : null,
        apr: parsed.apr != null ? Number(parsed.apr) : null,
        msrp: parsed.msrp != null ? Number(parsed.msrp) : null,
        offer_details: parsed.offer_details || null,
        title: parsed.title || originalItem.title || '',
        disclaimer: parsed.disclaimer || originalItem.disclaimer || '',
        expiration_date: parsed.expiration_date || null
      }
    }
  };
});
